+<footer><div class="shell footer-content"><span>© 2026 The Daily Grind. Crafted for coffee people, everywhere.</span><div class="footer-links"><a href="#" data-dialog="aboutDialog">Our story</a><a href="#" data-dialog="guideDialog">Tasting guide</a><span>Made with a little <span style="color:var(--accent)">♡</span></span></div></div></footer>
+<dialog id="guideDialog"><button class="dialog-close" aria-label="Close dialog">×</button><div class="eyebrow">A shared ritual</div><h2 style="margin-top:15px">A good tasting starts here.</h2><p>1. Choose your date, start time, and host time zone. Your host time zone is the place where you’re scheduling the event.</p><p>2. Compare local times for your coffee community. Add cities, check the dates, and find a moment that works for everyone.</p><p>3. Copy the tasting details to your invitation. Bring the same coffee, a favorite cup, and a little curiosity. Compare aroma, acidity, sweetness, and finish.</p><p>We check the actual time zone rules for your date. If clocks skip or repeat your chosen time, we’ll ask you to pick an unambiguous time.</p></dialog>
+<dialog id="aboutDialog"><button class="dialog-close" aria-label="Close dialog">×</button><div class="eyebrow">The Daily Grind</div><h2 style="margin-top:15px">Coffee brings us together.</h2><p>We believe a good cup is an invitation to connect. This tasting planner makes it a little easier to share that ritual with friends, wherever in the world they happen to be.</p><p>Pick your coffee. Find your moment. Pull up a chair.</p></dialog>
+<dialog id="zonesDialog"><button class="dialog-close" aria-label="Close dialog">×</button><h2>Your coffee community</h2><p>Choose the cities you’d like at your table. Your host city is always included.</p><div id="zoneOptions" class="zone-options"></div><button type="button" class="primary" id="saveZones">Update cities <svg><use href="#check"/></svg></button></dialog>
+<script>
+'use strict';
+const cities = [
+{city:'San Francisco',country:'United States',zone:'America/Los_Angeles',flag:'🇺🇸'},
+{city:'New York',country:'United States',zone:'America/New_York',flag:'🇺🇸'},
+{city:'London',country:'United Kingdom',zone:'Europe/London',flag:'🇬🇧'},
+{city:'Paris',country:'France',zone:'Europe/Paris',flag:'🇫🇷'},
+{city:'Tokyo',country:'Japan',zone:'Asia/Tokyo',flag:'🇯🇵'},
+{city:'Sydney',country:'Australia',zone:'Australia/Sydney',flag:'🇦🇺'},
+{city:'Vancouver',country:'Canada',zone:'America/Vancouver',flag:'🇨🇦'},
+{city:'São Paulo',country:'Brazil',zone:'America/Sao_Paulo',flag:'🇧🇷'},
+{city:'Berlin',country:'Germany',zone:'Europe/Berlin',flag:'🇩🇪'},
+{city:'Dubai',country:'United Arab Emirates',zone:'Asia/Dubai',flag:'🇦🇪'},
+{city:'Mumbai',country:'India',zone:'Asia/Kolkata',flag:'🇮🇳'},
+{city:'Singapore',country:'Singapore',zone:'Asia/Singapore',flag:'🇸🇬'},
+{city:'Auckland',country:'New Zealand',zone:'Pacific/Auckland',flag:'🇳🇿'}];
+const $ = id => document.getElementById(id);
+const dateInput=$('dateInput'), timeInput=$('timeInput'), hostTzSelect=$('hostTzSelect'), grid=$('grid');
+let selectedZones=cities.slice(0,6).map(c=>c.zone), use24=false, currentEvent=null;
+const formatters=new Map();
+function partsAt(timestamp,zone){
+ if(!formatters.has(zone)) formatters.set(zone,new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}));
+ return Object.fromEntries(formatters.get(zone).formatToParts(new Date(timestamp)).filter(p=>p.type!=='literal').map(p=>[p.type,Number(p.value)]));
+}
+function asUTC(p){const d=new Date(0);d.setUTCFullYear(p.year,p.month-1,p.day);d.setUTCHours(p.hour||0,p.minute||0,p.second||0,0);return d.getTime();}
+function offsetAt(timestamp,zone){return asUTC(partsAt(timestamp,zone))-Math.floor(timestamp/1000)*1000;}
+// Discover the offsets around the selected wall time, then round-trip every
+// candidate. Zero matches means a clock gap; two matches means a repeated time.
+function resolveWallTime(date,time,zone){
+ if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!/^\d{2}:\d{2}$/.test(time)) throw new Error('Choose a valid tasting date and start time.');
+ const [year,month,day]=date.split('-').map(Number), [hour,minute]=time.split(':').map(Number);
+ const desired={year,month,day,hour,minute,second:0}, wall=asUTC(desired), check=new Date(wall);
+ if(year<1900||year>2100||check.getUTCFullYear()!==year||check.getUTCMonth()+1!==month||check.getUTCDate()!==day||hour>23||minute>59) throw new Error('Choose a valid date between 1900 and 2100 and a valid start time.');
+ const offsets=new Set();
+ for(let h=-48;h<=48;h+=6) offsets.add(offsetAt(wall+h*3600000,zone));
+ const matches=[...offsets].map(offset=>wall-offset).filter(candidate=>{const actual=partsAt(candidate,zone);return Object.keys(desired).every(key=>desired[key]===actual[key]);});
+ if(!matches.length) throw new Error('This local time does not exist because the clocks move forward in your host time zone. Choose a time before or after the daylight saving gap.');
+ if(matches.length>1) throw new Error('This local time occurs twice because the clocks move back in your host time zone. Choose a time outside the repeated hour so everyone receives one unambiguous start time.');
+ return matches[0];
+}
+function escapeHTML(value){return String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
+function fmt(timestamp,zone,options){return new Intl.DateTimeFormat('en-US',{timeZone:zone,...options}).format(new Date(timestamp));}
+function dateKey(p){return `${p.year}-${String(p.month).padStart(2,'0')}-${String(p.day).padStart(2,'0')}`;}
+function zoneState(timestamp,zone){
+ const offset=offsetAt(timestamp,zone), year=partsAt(timestamp,zone).year;
+ const jan=offsetAt(Date.UTC(year,0,15,12),zone), jul=offsetAt(Date.UTC(year,6,15,12),zone);
+ const seasonal=jan!==jul, dst=seasonal && offset>Math.min(jan,jul);
+ const mins=Math.round(offset/60000), abs=Math.abs(mins);
+ return {dst,seasonal,offset:`UTC${mins>=0?'+':'−'}${String(Math.floor(abs/60)).padStart(2,'0')}:${String(abs%60).padStart(2,'0')}`};
+}
+function visibleCities(){return cities.filter(c=>selectedZones.includes(c.zone)||c.zone===hostTzSelect.value);}
+function render(){
+ if(!currentEvent)return;
+ const {instant,hostZone}=currentEvent, hostDay=asUTC({...partsAt(instant,hostZone),hour:0,minute:0,second:0});
+ const shown=visibleCities(); $('zoneCount').textContent=`${shown.length} cities`;
+ $('eventSummary').textContent=`${fmt(instant,hostZone,{weekday:'long',month:'long',day:'numeric',year:'numeric'})} · One moment, shared worldwide.`;
+ grid.innerHTML=shown.map(c=>{
+ const p=partsAt(instant,c.zone), state=zoneState(instant,c.zone), host=c.zone===hostZone;
+ const dayDelta=Math.round((asUTC({...p,hour:0,minute:0,second:0})-hostDay)/86400000);
+ const timeParts=new Intl.DateTimeFormat('en-US',{timeZone:c.zone,hour:'2-digit',minute:'2-digit',hourCycle:use24?'h23':'h12'}).formatToParts(new Date(instant));
+ const clock=timeParts.filter(p=>p.type!=='dayPeriod'&&!(p.type==='literal'&&p.value.trim()==='')).map(p=>p.value).join('');
+ const period=timeParts.find(p=>p.type==='dayPeriod')?.value||'';
+ const abbr=fmt(instant,c.zone,{timeZoneName:'short'}).split(', ').pop().split(' ').pop();
+ return `<article class="zone-card ${host?'host':''}" aria-label="${escapeHTML(c.city)} local tasting time"><div class="card-top"><div class="city"><span class="flag" aria-hidden="true">${c.flag}</span>${c.city}${host?'<span class="host-tag">HOST</span>':''}</div><svg class="period-icon" aria-label="${p.hour>=6&&p.hour<18?'Daytime':'Nighttime'}"><use href="#${p.hour>=6&&p.hour<18?'sun':'moon'}"/></svg></div><div class="country">${c.country}</div><div class="time">${escapeHTML(clock)}<span>${period}</span></div><div class="local-date">${fmt(instant,c.zone,{weekday:'short',month:'short',day:'numeric',year:'numeric'})}${dayDelta?`<span class="day-shift">${dayDelta>0?'+':''}${dayDelta} day${Math.abs(dayDelta)>1?'s':''}</span>`:''}</div><div class="card-bottom"><span class="offset">${escapeHTML(abbr)} · ${state.offset}</span><span class="dst-tag">${state.dst?'<i></i>DST observed':state.seasonal?'Standard time':'No daylight saving'}</span></div></article>`;
+ }).join('');
+ $('copyEvent').disabled=false;
+}
+function update(){
+ $('copyStatus').textContent='';
+ try{
+ const instant=resolveWallTime(dateInput.value,timeInput.value,hostTzSelect.value);
+ currentEvent={instant,hostZone:hostTzSelect.value};$('error').hidden=true;
+ dateInput.removeAttribute('aria-invalid');timeInput.removeAttribute('aria-invalid');render();
+ }catch(error){
+ currentEvent=null;$('error').textContent=error.message;$('error').hidden=false;timeInput.setAttribute('aria-invalid','true');
+ grid.innerHTML='<div class="empty">Choose a valid host date and time to see everyone’s local tasting time.</div>';
+ $('eventSummary').textContent='Waiting for a valid tasting time.';$('copyEvent').disabled=true;
+ }
+}
+for(const c of cities){const option=new Option(`${c.city} (${c.zone.replaceAll('_',' ')})`,c.zone);hostTzSelect.add(option);}
+hostTzSelect.value='America/New_York';
+const today=partsAt(Date.now(),hostTzSelect.value);dateInput.value=dateKey(today);
+$('eventForm').addEventListener('submit',event=>{event.preventDefault();update();});
+for(const input of [dateInput,timeInput,hostTzSelect]) input.addEventListener('change',update);
+for(const [id,value] of [['format12',false],['format24',true]]) $(id).addEventListener('click',()=>{use24=value;for(const [button,is24] of [['format12',false],['format24',true]]){$(button).classList.toggle('selected',use24===is24);$(button).setAttribute('aria-pressed',String(use24===is24));}render();});
+document.querySelectorAll('[data-dialog]').forEach(link=>link.addEventListener('click',e=>{e.preventDefault();$(link.dataset.dialog).showModal();}));
+document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});});
+$('addZones').addEventListener('click',()=>{
+ $('zoneOptions').innerHTML=cities.map(c=>`<label><input type="checkbox" value="${c.zone}" ${selectedZones.includes(c.zone)||c.zone===hostTzSelect.value?'checked':''} ${c.zone===hostTzSelect.value?'disabled':''}><span>${c.flag} ${c.city}</span>${c.zone===hostTzSelect.value?'<span class="host-tag">HOST</span>':''}</label>`).join('');$('zonesDialog').showModal();
+});
+$('saveZones').addEventListener('click',()=>{selectedZones=[...$('zoneOptions').querySelectorAll('input:checked')].map(input=>input.value);$('zonesDialog').close();render();});
+$('copyEvent').addEventListener('click',async()=>{
+ if(!currentEvent)return;
+ const {instant}=currentEvent;
+ const text='The Daily Grind — Global Coffee Tasting\n'+visibleCities().map(c=>`${c.city}: ${fmt(instant,c.zone,{weekday:'short',year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',hourCycle:use24?'h23':'h12',timeZoneName:'short'})} (${c.zone})`).join('\n')+'\n\nBring your favorite cup. Let’s taste together!';
+ try{if(!navigator.clipboard?.writeText)throw new Error('unavailable');await navigator.clipboard.writeText(text);$('copyStatus').textContent='Tasting details copied. Ready for your invitation.';}catch{const area=document.createElement('textarea');area.value=text;area.style.cssText='position:fixed;left:-9999px';document.body.append(area);area.select();let copied=false;try{copied=document.execCommand('copy');}catch{}area.remove();$('copyStatus').textContent=copied?'Tasting details copied. Ready for your invitation.':'Copy is unavailable in this browser. Select and copy the city times above.';}
+});
+update();
+</script>
 </body>
