diff --git a/scripts/check-renderer.mjs b/scripts/check-renderer.mjs
new file mode 100644
index 0000000..c0947d1
--- /dev/null
+++ b/scripts/check-renderer.mjs
@@ -0,0 +1,30 @@
+import assert from 'node:assert/strict';
+import { readFileSync } from 'node:fs';
+import init from '../assets/smallpt.js';
+const binary = readFileSync(new URL('../assets/smallpt.wasm', import.meta.url));
+assert(WebAssembly.validate(binary), 'Invalid Wasm binary');
+const renderer = await init({ wasmBinary: binary });
+function render(width, height, seed, passes) {
+  renderer._initialize(width, height, seed);
+  for (let pass = 0; pass < passes; pass++) {
+    for (let row = 0; row < height; row += 8) renderer._render_rows(row, 8);
+    renderer._finish_pass();
+  }
+  const ptr = renderer._get_pixels();
+  return renderer.HEAPU8.slice(ptr, ptr + width * height * 4);
+}
+const original = render(48, 36, 1234, 4);
+assert(original.some((v, i) => i % 4 !== 3 && v > 0), 'Output is black');
+assert(original.every((v, i) => i % 4 !== 3 || v === 255), 'Invalid alpha');
+assert.deepEqual(render(48, 36, 1234, 4), original, 'Seeded output is not deterministic');
+assert.notDeepEqual(render(48, 36, 1234, 1), original, 'Progressive passes did not refine the image');
+renderer._set_color(6, .9, .2, .3);
+renderer._set_color(7, .2, .8, .3);
+const changed = render(48, 36, 1234, 4);
+assert(changed.filter((value, i) => value !== original[i]).length > 100, 'Sphere colors did not change the render');
+const start = performance.now();
+const large = render(640, 480, 1234, 1);
+assert.equal(large.length, 640 * 480 * 4);
+assert(large.every((v, i) => i % 4 !== 3 || v === 255), 'Memory growth corrupted output');
+console.log('PASS: Wasm validation, RGBA output, deterministic seeds, progressive samples, sphere color rerender, and 640×480 memory growth.');
+console.log(`640×480 first pass: ${((performance.now() - start) / 1000).toFixed(2)} s`);
