+        position: relative;
+    }
+
+    .section-view.inactive {
+        content-visibility: hidden;
+        position: absolute;
+        inset: 0 0 auto;
+        height: 0;
+        overflow: hidden;
+        contain-intrinsic-size: 0 0;
+    }
+
+    @supports not (content-visibility: hidden) {
+        .section-view.inactive {
+            display: none;
+        }
+    }
+</style>
