new file mode 100644
index 0000000..dfa1cfa
--- /dev/null
+++ b/src/components/ModalDialog.tsx
@@ -0,0 +1,41 @@
+import { useEffect, useRef, type ReactNode } from 'react';
+
+interface Props {
+  id: string;
+  title: string;
+  onClose: () => void;
+  children: ReactNode;
+}
+
+export default function ModalDialog({ id, title, onClose, children }: Props) {
+  const ref = useRef<HTMLDialogElement>(null);
+
+  useEffect(() => {
+    const dialog = ref.current!;
+    const trigger = document.activeElement instanceof HTMLElement ? document.activeElement : null;
+    dialog.showModal();
+    return () => {
+      dialog.close();
+      if (trigger?.isConnected) trigger.focus();
+    };
+  }, []);
+
+  return (
+    <dialog ref={ref} id={id} aria-labelledby={`${id}-title`}
+      closedby="any" className="modal-dialog" onClose={onClose}
+      onClick={event => {
+        // Backdrop dismissal for browsers without closedby support. Padding clicks stay inside.
+        if (event.target !== event.currentTarget) return;
+        const rect = event.currentTarget.getBoundingClientRect();
+        if (event.clientX < rect.left || event.clientX > rect.right || event.clientY < rect.top || event.clientY > rect.bottom) {
+          event.currentTarget.close();
+        }
+      }}>
+      <div className="flex items-center justify-between gap-4 p-4 border-b border-gray-200">
+        <h2 id={`${id}-title`} className="text-lg font-semibold">{title}</h2>
+        <form method="dialog"><button className="p-2 text-sm font-semibold" type="submit">Close</button></form>
+      </div>
+      {children}
+    </dialog>
+  );
+}
diff --git a/src/components/Popover.tsx b/src/components/Popover.tsx
new file mode 100644
index 0000000..5ebddd3
--- /dev/null
+++ b/src/components/Popover.tsx
@@ -0,0 +1,32 @@
+import { useId, useRef, useState, type ReactNode } from 'react';
+
+export default function Popover({ label, children, active = false }: {
+  label: ReactNode; children: ReactNode; active?: boolean;
+}) {
+  const id = useId();
+  const trigger = useRef<HTMLButtonElement>(null);
+  const [open, setOpen] = useState(false);
+  return (
+    <div className="h-full flex items-center">
+      <button ref={trigger} type="button" popoverTarget={id} aria-expanded={open} aria-controls={id}
+        className={`flex items-center gap-1 whitespace-nowrap hover:underline ${active ? 'text-amber-700' : ''}`}>
+        {label}<span aria-hidden="true">⌄</span>
+      </button>
+      <div id={id} popover="auto" className="nav-popover bg-white border border-gray-300 shadow-lg p-6"
+        onBeforeToggle={event => {
+          if (event.newState !== 'open') return;
+          const rect = trigger.current!.getBoundingClientRect();
+          event.currentTarget.style.setProperty('--popover-top', `${rect.bottom + 8}px`);
+        }}
+        onToggle={event => {
+          setOpen(event.newState === 'open');
+          if (event.newState === 'closed' && event.currentTarget.contains(document.activeElement)) trigger.current?.focus();
+        }}
+        onClick={event => {
+          if ((event.target as HTMLElement).closest('a')) event.currentTarget.hidePopover();
+        }}>
+        {children}
+      </div>
+    </div>
+  );
+}
