diff --git a/tests/reviews.test.cjs b/tests/reviews.test.cjs
new file mode 100644
index 0000000..47625e3
--- /dev/null
+++ b/tests/reviews.test.cjs
@@ -0,0 +1,104 @@
+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const { readFileSync } = require('node:fs');
+const { JSDOM } = require('jsdom');
+
+const html = readFileSync('index.html', 'utf8');
+const purifier = readFileSync('vendor/purify.min.js', 'utf8');
+
+function setup(loadSanitizer = true) {
+  // No network, server, or browser: execute the page code in an isolated DOM.
+  const dom = new JSDOM(html, { runScripts: 'outside-only' });
+  if (loadSanitizer) dom.window.eval(purifier);
+  for (const script of dom.window.document.querySelectorAll('script:not([src])')) {
+    dom.window.eval(script.textContent);
+  }
+  return dom;
+}
+
+function submit(dom, index, markup, name = 'Coffee fan') {
+  const form = dom.window.document.querySelectorAll('.review-form')[index];
+  form.elements.namedItem('reviewer').value = name;
+  form.elements.namedItem('feedback').value = markup;
+  form.dispatchEvent(new dom.window.Event('submit', { bubbles: true, cancelable: true }));
+  return form.closest('.reviews');
+}
+
+test('each drink accepts formatted reviews in its own list and resets the form', () => {
+  const dom = setup();
+  try {
+    for (let index = 0; index < 3; index++) {
+      const section = submit(dom, index, '<p>Lovely <strong>coffee</strong> with <em>oat milk</em>.</p><ul><li>Smooth</li></ul>');
+      assert.equal(section.querySelectorAll('.review-list > li').length, 1);
+      assert.equal(section.querySelector('.review-body strong').textContent, 'coffee');
+      assert.equal(section.querySelector('.review-body em').textContent, 'oat milk');
+      assert.equal(section.querySelector('.review-body li').textContent, 'Smooth');
+      assert.equal(section.querySelector('.review-empty').hidden, true);
+      assert.equal(section.querySelector('textarea').value, '');
+      assert.match(section.querySelector('.review-status').textContent, /posted/);
+    }
+    submit(dom, 0, 'A second review');
+    assert.deepEqual(Array.from(dom.window.document.querySelectorAll('.review-list'), list => list.children.length), [2, 1, 1]);
+  } finally {
+    dom.window.close();
+  }
+});
+
+test('untrusted names stay text and malicious markup loses executable elements and attributes', () => {
+  const dom = setup();
+  const payloads = [
+    '<script>window.pwned = true</script><p onclick="alert(1)" style="position:fixed" id="review-form" data-x="1" aria-label="fake">Good <strong onmouseover="alert(1)">coffee</strong></p>',
+    '<img src=x onerror="alert(1)"><iframe srcdoc="<script>alert(1)</script>"></iframe><object data="javascript:alert(1)"></object><p>Good</p>',
+    '<a href="javascript:alert(1)" target="_blank">Good</a><a href="data:text/html,bad">coffee</a>',
+    '<svg><g onload="alert(1)"></g><foreignObject><p onclick="alert(1)">bad</p></foreignObject></svg><math><mtext><img src=x onerror="alert(1)"></mtext></math><p>Good</p>',
+    '<math><mtext><table><mglyph><style><!--</style><img title="--><img src=x onerror=alert(1)>"></table></mtext></math><p>Good</p>',
+    '<form id="reviews"><input name="append"><textarea>bad</textarea></form><style>body{display:none}</style><p>Good</p>'
+  ];
+  const allowed = new Set(['P', 'BR', 'STRONG', 'B', 'EM', 'I', 'U', 'S', 'UL', 'OL', 'LI', 'BLOCKQUOTE', 'CODE']);
+  try {
+    for (const payload of payloads) {
+      const name = '<img src=x onerror=alert(1)>';
+      const section = submit(dom, 0, payload, name);
+      const entry = section.querySelector('.review-list').lastElementChild;
+      assert.ok(entry);
+      assert.equal(entry.querySelector('h5').textContent, name);
+      assert.equal(entry.querySelector('h5').children.length, 0);
+      for (const element of entry.querySelectorAll('.review-body *')) {
+        assert.ok(allowed.has(element.tagName), `Unexpected element: ${element.tagName}`);
+        assert.equal(element.attributes.length, 0, `Attributes survived on ${element.tagName}`);
+      }
+      assert.equal(dom.window.pwned, undefined);
+    }
+    assert.equal(dom.window.document.querySelectorAll('.review-list > li').length, payloads.length);
+  } finally {
+    dom.window.close();
+  }
+});
+
+test('blank, overlong, and sanitized-empty submissions do not add reviews', () => {
+  const dom = setup();
+  try {
+    submit(dom, 0, '<script>alert(1)</script><img src=x onerror=alert(1)>');
+    assert.match(dom.window.document.querySelector('.review-status').textContent, /include some review text/);
+    submit(dom, 0, '   ');
+    submit(dom, 0, 'Good', '   ');
+    submit(dom, 0, 'x'.repeat(5001));
+    submit(dom, 0, 'Good', 'x'.repeat(81));
+    assert.equal(dom.window.document.querySelectorAll('.review-list > li').length, 0);
+    assert.equal(dom.window.document.querySelector('.review-empty').hidden, false);
+  } finally {
+    dom.window.close();
+  }
+});
+
+test('review submission stays disabled if the sanitizer is unavailable', () => {
+  const dom = setup(false);
+  try {
+    for (const form of dom.window.document.querySelectorAll('.review-form')) {
+      assert.equal(form.querySelector('button').disabled, true);
+      assert.match(form.querySelector('.review-status').textContent, /unavailable/);
+    }
+  } finally {
+    dom.window.close();
+  }
+});
