1/schedule-tasks-by-priority/task/guided:
diff --git a/index.html b/index.html
--- a/index.html
+++ b/index.html
@@ -134,8 +134,74 @@
     .btn:hover {
       background: #3e2723;
     }

+    .operations {
+      margin-top: 48px;
+      padding: 28px;
+      border: 1px solid var(--secondary);
+      border-radius: 12px;
+      background: #fffdfb;
+    }
+
+    .operations-header, .queue-summary, .task-line {
+      display: flex;
+      align-items: center;
+      justify-content: space-between;
+      flex-wrap: wrap;
+      gap: 12px;
+    }
+
+    .eyebrow {
+      color: #795548;
+      font-size: 0.75rem;
+      font-weight: 700;
+      letter-spacing: 0.12em;
+      text-transform: uppercase;
+    }
+
+    .operations h2 { margin: 4px 0; }
+    .operations-description { margin: 10px 0 20px; color: #6d534b; }
+    .queue-status { font-size: 0.85rem; color: #365b3b; }
+    .queue-status::before { content: '●'; margin-right: 7px; }
+    .operation-controls { display: flex; flex-wrap: wrap; gap: 10px; }
+
+    .operation-controls button {
+      padding: 11px 15px;
+      border: 1px solid var(--secondary);
+      border-radius: 6px;
+      background: white;
+      color: var(--primary);
+      cursor: pointer;
+      font: 600 0.875rem/1.4 'Segoe UI', sans-serif;
+    }
+
+    .operation-controls button:hover { background: #f2ebe6; }
+    .operation-controls .urgent { border-color: #ad5634; color: #943c20; }
+    .operation-controls .batch { background: var(--primary); color: white; border-color: var(--primary); }
+    .operation-controls .batch:hover { background: #3e2723; }
+    .operations button:focus-visible { outline: 3px solid #bd6b00; outline-offset: 3px; }
+    .operations button:disabled { cursor: wait; opacity: 0.55; }
+    .queue-summary { margin-top: 24px; padding-top: 18px; border-top: 1px solid #e9dfda; font-size: 0.85rem; }
+    .queue-summary strong { font-variant-numeric: tabular-nums; }
+    .queue-rule { color: #795548; font-size: 0.8rem; }
+    .queue-tasks { list-style: none; display: grid; gap: 10px; margin: 16px 0; }
+    .queue-task { padding: 12px 14px; border: 1px solid #e9dfda; border-radius: 6px; background: white; }
+    .task-line { font-size: 0.85rem; gap: 4px 12px; }
+    .task-detail { color: #795548; font-size: 0.75rem; }
+    .queue-task progress { display: block; width: 100%; height: 6px; margin-top: 9px; accent-color: var(--primary); }
+    .queue-empty { padding: 20px 0; color: #795548; font-size: 0.9rem; }
+    .operations details { border-top: 1px solid #e9dfda; padding-top: 14px; }
