+    font-weight: bold;
+    letter-spacing: 1px;
+  }
+  #links {
+    display: flex;
+    flex-wrap: wrap;
+    gap: 20px;
+    align-items: center;
+  }
+  ::slotted(a) {
+    color: white;
+    text-decoration: none;
+    font-size: 0.9rem;
+    padding-block: 8px;
+  }
+  ::slotted(a:hover) { color: var(--accent, #ffab40); }
